use std::fs

fn is_int(t: string) -> bool {
    let cs: Vec<char> = t.chars().collect()
    let n: int = cs.len() as int
    let mut ok = n > 0
    let mut digits: int = 0
    let mut i: int = 0
    while i < n {
        let c = cs[i]
        if c >= '0' && c <= '9' {
            digits += 1
        } else if !(c == '-' && i == 0) {
            ok = false
        }
        i += 1
    }
    ok && digits > 0
}

fn is_op(t: string) -> bool {
    t == "+" || t == "-" || t == "*" || t == "/"
}

fn eval(line: string) -> string {
    let mut st: Vec<int> = []
    let mut err = ""
    for t in line.split(" ") {
        if err != "" || t == "" {
            continue
        }
        if is_op(t) {
            if st.len() < 2 {
                err = "error: underflow"
            } else {
                let b = st.pop().unwrap_or(0)
                let a = st.pop().unwrap_or(0)
                if t == "+" {
                    st.push(a + b)
                } else if t == "-" {
                    st.push(a - b)
                } else if t == "*" {
                    st.push(a * b)
                } else if b == 0 {
                    err = "error: divzero"
                } else {
                    st.push(a / b)
                }
            }
        } else if is_int(t) {
            let v: int = t.parse::<int>().unwrap_or(0)
            st.push(v)
        } else {
            err = "error: token"
        }
    }
    if err != "" {
        err
    } else if st.len() != 1 {
        "error: leftover"
    } else {
        "${st[0]}"
    }
}

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    for line in text.lines() {
        let l = line.trim()
        if l != "" {
            println(eval(l))
        }
    }
}

